## Fixing Race Conditions in PostgreSQL Counter Increments

This is a classic race condition where multiple requests read the same value before any write completes. Here's how to fix it properly.

## The Problem

```javascript
// ❌ BROKEN - Classic read-modify-write race condition
app.post('/increment', async (req, res) => {
  const result = await db.query('SELECT counter FROM counts WHERE id = $1', [id]);
  const newValue = result.rows[0].counter + 1;
  await db.query('UPDATE counts SET counter = $1 WHERE id = $2', [newValue, id]);
  res.json({ counter: newValue }); // Multiple requests get the same value!
});
```

**What happens with concurrent requests:**
```
Request A: READ  counter = 5
Request B: READ  counter = 5   ← reads before A writes
Request A: WRITE counter = 6
Request B: WRITE counter = 6   ← overwrites A, value should be 7!
```

---

## Solution 1: Atomic SQL Update (Best for Simple Counters)

```javascript
// ✅ Single atomic operation - no race condition possible
app.post('/increment', async (req, res) => {
  const result = await db.query(
    `UPDATE counts 
     SET counter = counter + 1 
     WHERE id = $1 
     RETURNING counter`,
    [id]
  );

  res.json({ counter: result.rows[0].counter });
});
```

**Why this works:** PostgreSQL executes this as a single atomic operation with a row-level lock. No separate read step exists for another transaction to interleave with.

---

## Solution 2: Transactions with SELECT FOR UPDATE (Best for Complex Logic)

```javascript
// ✅ Explicit locking when you need to read before writing
app.post('/increment', async (req, res) => {
  const client = await db.pool.connect();

  try {
    await client.query('BEGIN');

    // FOR UPDATE locks the row until transaction completes
    const result = await client.query(
      'SELECT counter FROM counts WHERE id = $1 FOR UPDATE',
      [id]
    );

    const newValue = result.rows[0].counter + 1;

    // Apply business logic here if needed
    // e.g., validate limits, log history, update related tables

    const updated = await client.query(
      'UPDATE counts SET counter = $1 WHERE id = $2 RETURNING counter',
      [newValue, id]
    );

    await client.query('COMMIT');
    res.json({ counter: updated.rows[0].counter });

  } catch (err) {
    await client.query('ROLLBACK');
    throw err;
  } finally {
    client.release(); // Always release back to pool
  }
});
```

---

## Solution 3: Upsert Pattern (Best for Insert-or-Increment)

```javascript
// ✅ Handles the case where the row might not exist yet
app.post('/increment', async (req, res) => {
  const result = await db.query(
    `INSERT INTO counts (id, counter) 
     VALUES ($1, 1)
     ON CONFLICT (id) 
     DO UPDATE SET counter = counts.counter + 1
     RETURNING counter`,
    [id]
  );

  res.json({ counter: result.rows[0].counter });
});
```

---

## Solution 4: Advisory Locks (Best for Application-Level Coordination)

```javascript
// ✅ Useful when you can't modify the query structure
app.post('/increment', async (req, res) => {
  const lockId = hashToInt(id); // Convert your ID to an integer
  const client = await db.pool.connect();

  try {
    // Acquire application-level lock
    await client.query('SELECT pg_advisory_lock($1)', [lockId]);

    const result = await client.query(
      'SELECT counter FROM counts WHERE id = $1',
      [id]
    );
    const newValue = result.rows[0].counter + 1;

    await client.query(
      'UPDATE counts SET counter = $1 WHERE id = $2',
      [newValue, id]
    );

    res.json({ counter: newValue });

  } finally {
    await client.query('SELECT pg_advisory_unlock($1)', [lockId]);
    client.release();
  }
});

function hashToInt(str) {
  // Simple hash - use a proper hash function in production
  return str.split('').reduce((acc, char) => acc + char.charCodeAt(0), 0);
}
```

---

## Proper Error Handling Wrapper

```javascript
// Reusable transaction helper to avoid repetitive try/catch
async function withTransaction(pool, callback) {
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    const result = await callback(client);
    await client.query('COMMIT');
    return result;
  } catch (err) {
    await client.query('ROLLBACK');
    throw err;
  } finally {
    client.release();
  }
}

// Clean usage
app.post('/increment', async (req, res) => {
  const counter = await withTransaction(db.pool, async (client) => {
    const result = await client.query(
      `UPDATE counts SET counter = counter + 1 WHERE id = $1 RETURNING counter`,
      [id]
    );
    return result.rows[0].counter;
  });

  res.json({ counter });
});
```

---

## Which Solution to Choose?

| Scenario | Solution |
|----------|----------|
| Simple counter increment | Atomic `UPDATE counter = counter + 1` |
| Need to read value before complex logic | Transaction + `SELECT FOR UPDATE` |
| Row may not exist yet | Upsert with `ON CONFLICT` |
| Cross-table coordination | Advisory locks |
| High contention, can tolerate retries | Optimistic locking with version column |

---

## Key Takeaways

- **Never** do read-then-write as separate queries without locking
- **Prefer** atomic SQL operations when possible — they're simpler and faster
- **Always** release connections in a `finally` block to prevent pool exhaustion
- **Test** concurrency with tools like `artillery` or `k6` to verify your fix works
